import React from "react";
import { render, fireEvent } from "@testing-library/react-native";
import CoinsDisplay from "../CoinsDisplay";

describe("CoinsDisplay", () => {
  describe("Rendering", () => {
    it("renders coin icon and amount correctly", () => {
      const { getByText } = render(<CoinsDisplay coins={100} />);

      expect(getByText("100")).toBeTruthy();
    });

    it("renders zero coins correctly", () => {
      const { getByText } = render(<CoinsDisplay coins={0} />);

      expect(getByText("0")).toBeTruthy();
    });

    it("renders large coin amounts correctly", () => {
      const { getByText } = render(<CoinsDisplay coins={999999} />);

      expect(getByText("999999")).toBeTruthy();
    });

    it("renders negative coin amounts correctly", () => {
      const { getByText } = render(<CoinsDisplay coins={-50} />);

      expect(getByText("-50")).toBeTruthy();
    });

    it("renders decimal coin amounts correctly", () => {
      const { getByText } = render(<CoinsDisplay coins={123.45} />);

      expect(getByText("123.45")).toBeTruthy();
    });
  });

  describe("Touchable Behavior", () => {
    it("renders as TouchableOpacity when onPress is provided", () => {
      const onPress = jest.fn();
      const { getByTestId } = render(
        <CoinsDisplay coins={100} onPress={onPress} />
      );

      // Should be wrapped in TouchableOpacity
      const touchable = getByTestId("coins-display-touchable");
      expect(touchable).toBeTruthy();
    });

    it("renders as View when onPress is not provided", () => {
      const { queryByTestId } = render(<CoinsDisplay coins={100} />);

      // Should not be wrapped in TouchableOpacity
      const touchable = queryByTestId("coins-display-touchable");
      expect(touchable).toBeNull();
    });

    it("calls onPress when touched", () => {
      const onPress = jest.fn();
      const { getByTestId } = render(
        <CoinsDisplay coins={100} onPress={onPress} />
      );

      const touchable = getByTestId("coins-display-touchable");
      fireEvent.press(touchable);

      expect(onPress).toHaveBeenCalledTimes(1);
    });

    it("calls onPress multiple times when touched multiple times", () => {
      const onPress = jest.fn();
      const { getByTestId } = render(
        <CoinsDisplay coins={100} onPress={onPress} />
      );

      const touchable = getByTestId("coins-display-touchable");
      fireEvent.press(touchable);
      fireEvent.press(touchable);
      fireEvent.press(touchable);

      expect(onPress).toHaveBeenCalledTimes(3);
    });

    it("does not call onPress when not provided", () => {
      const { getByTestId } = render(<CoinsDisplay coins={100} />);

      // Should not throw error when trying to press non-touchable element
      const coinsDisplay = getByTestId("coins-display");
      expect(() => fireEvent.press(coinsDisplay)).not.toThrow();
    });
  });

  describe("Accessibility", () => {
    it("has proper accessibility properties when touchable", () => {
      const onPress = jest.fn();
      const { getByTestId } = render(
        <CoinsDisplay coins={100} onPress={onPress} />
      );

      const touchable = getByTestId("coins-display-touchable");
      expect(touchable.props.accessible).toBeTruthy();
      expect(touchable.props.accessibilityRole).toBe("button");
      expect(touchable.props.accessibilityLabel).toBe(
        "Open coin shop. You have 100 coins"
      );
    });

    it("has proper accessibility properties when not touchable", () => {
      const { getByTestId } = render(<CoinsDisplay coins={100} />);

      const coinsDisplay = getByTestId("coins-display");
      expect(coinsDisplay.props.accessible).toBeTruthy();
      expect(coinsDisplay.props.accessibilityLabel).toBe("You have 100 coins");
    });

    it("has proper accessibility label for zero coins", () => {
      const { getByTestId } = render(<CoinsDisplay coins={0} />);

      const coinsDisplay = getByTestId("coins-display");
      expect(coinsDisplay.props.accessibilityLabel).toBe("You have 0 coins");
    });

    it("has proper accessibility label for one coin", () => {
      const { getByTestId } = render(<CoinsDisplay coins={1} />);

      const coinsDisplay = getByTestId("coins-display");
      expect(coinsDisplay.props.accessibilityLabel).toBe("You have 1 coin");
    });

    it("has proper accessibility label for multiple coins", () => {
      const { getByTestId } = render(<CoinsDisplay coins={50} />);

      const coinsDisplay = getByTestId("coins-display");
      expect(coinsDisplay.props.accessibilityLabel).toBe("You have 50 coins");
    });
  });

  describe("Visual Structure", () => {
    it("contains coin icon and text in flex-row layout", () => {
      const { getByTestId } = render(<CoinsDisplay coins={100} />);

      const container = getByTestId("coins-display");
      expect(container.props.style).toMatchObject({
        flexDirection: "row",
        alignItems: "center",
      });
    });

    it("displays coin icon with correct dimensions", () => {
      const { getByTestId } = render(<CoinsDisplay coins={100} />);

      const coinIcon = getByTestId("coin-icon");
      expect(coinIcon.props.width).toBe(24);
      expect(coinIcon.props.height).toBe(24);
    });

    it("displays coin text with correct styling", () => {
      const { getByText } = render(<CoinsDisplay coins={100} />);

      const coinText = getByText("100");
      expect(coinText.props.style).toMatchObject({
        fontSize: 18,
        fontWeight: "bold",
        color: "#1f2937", // text-gray-800
        marginLeft: 4,
      });
    });
  });

  describe("Edge Cases", () => {
    it("handles undefined onPress gracefully", () => {
      const { getByTestId } = render(
        <CoinsDisplay coins={100} onPress={undefined} />
      );

      // Should render as non-touchable
      const coinsDisplay = getByTestId("coins-display");
      expect(coinsDisplay).toBeTruthy();
      expect(() => fireEvent.press(coinsDisplay)).not.toThrow();
    });

    it("handles null coins gracefully", () => {
      const { getByText } = render(<CoinsDisplay coins={null as any} />);

      expect(getByText("")).toBeTruthy();
    });

    it("handles string coins gracefully", () => {
      const { getByText } = render(<CoinsDisplay coins={"100" as any} />);

      expect(getByText("100")).toBeTruthy();
    });

    it("handles very large numbers", () => {
      const { getByText } = render(
        <CoinsDisplay coins={Number.MAX_SAFE_INTEGER} />
      );

      expect(getByText(Number.MAX_SAFE_INTEGER.toString())).toBeTruthy();
    });

    it("handles very small numbers", () => {
      const { getByText } = render(
        <CoinsDisplay coins={Number.MIN_SAFE_INTEGER} />
      );

      expect(getByText(Number.MIN_SAFE_INTEGER.toString())).toBeTruthy();
    });
  });

  describe("Performance", () => {
    it("does not re-render unnecessarily when coins stay the same", () => {
      const onPress = jest.fn();
      const { rerender } = render(
        <CoinsDisplay coins={100} onPress={onPress} />
      );

      // Re-render with same props
      rerender(<CoinsDisplay coins={100} onPress={onPress} />);

      // Component should handle this efficiently
      expect(onPress).not.toHaveBeenCalled();
    });

    it("updates correctly when coins change", () => {
      const { getByText, rerender } = render(<CoinsDisplay coins={100} />);

      expect(getByText("100")).toBeTruthy();

      rerender(<CoinsDisplay coins={200} />);
      expect(getByText("200")).toBeTruthy();
    });

    it("updates correctly when onPress changes", () => {
      const onPress1 = jest.fn();
      const onPress2 = jest.fn();
      const { getByTestId, rerender } = render(
        <CoinsDisplay coins={100} onPress={onPress1} />
      );

      const touchable1 = getByTestId("coins-display-touchable");
      fireEvent.press(touchable1);
      expect(onPress1).toHaveBeenCalledTimes(1);

      rerender(<CoinsDisplay coins={100} onPress={onPress2} />);
      const touchable2 = getByTestId("coins-display-touchable");
      fireEvent.press(touchable2);
      expect(onPress2).toHaveBeenCalledTimes(1);
      expect(onPress1).toHaveBeenCalledTimes(1); // Should not be called again
    });
  });
});
